module {
  func.func @main(%a: tensor<2x7xf32>, %b: tensor<4x7xf32>) -> tensor<2x4xf32> {
    // Transpose %b to align dimensions for dot product
    %b_transposed = "stablehlo.transpose"(%b) {permutation = dense<[1, 0]>} : (tensor<4x7xf32>) -> tensor<7x4xf32>
    // Perform dot product between %a and transposed %b
    %out = "stablehlo.dot_general"(%a, %b_transposed) {
      dot_dimension_numbers = #stablehlo.dot<lhs_contracting_dimensions = [1], rhs_contracting_dimensions = [1]>
    } : (tensor<2x7xf32>, tensor<7x4xf32>) -> tensor<2x4xf32>
    return %out : tensor<2x4xf32>
  }
}
