```mlir
// StableHLO program to compute lower triangular mask
module {
  func @main(%x: tensor<6x6xf32>) -> tensor<6x6xf32> {
    // Generate row indices (iota along the first dimension)
    %rows = "stablehlo.iota"() {iota_dimension = 0 : i64, iota_shape = tensor<6x6xi32>} : () -> tensor<6x6xi32>
    // Generate column indices (iota along the second dimension)
    %cols = "stablehlo.iota"() {iota_dimension = 1 : i64, iota_shape = tensor<6x6xi32>} : () -> tensor<6x6xi32>
    // Convert indices to float for comparison
    %rows_f32 = "stablehlo.convert"(%rows) {to_dtype = f32} : (tensor<6x6xi32>) -> tensor<6x6xf32>
    %cols_f32 = "stablehlo.convert"(%cols) {to_dtype = f32} : (tensor<6x6xi32>) -> tensor<6x6xf32>
    // Compare if column index <= row index
    %cmp = "stablehlo.compare"(%cols_f32, %rows_f32) {comparison_direction = "LE"} : (tensor<6x6xf32>, tensor<6x6xf32>) -> tensor<6x6xi1>
    // Convert boolean mask to float (1.0 for true, 0.0 for false)
    %mask_float = "stablehlo.convert"(%cmp) {to_dtype = f32} : (tensor<6x6xi1>) -> tensor<6x6xf32>
    // Multiply input by mask to keep lower triangle, zero out others
    %out = "stablehlo.multiply"(%x, %mask_float) : (tensor<6x6xf32>, tensor<6x6xf32>) -> tensor<6x6xf32>
    return %out : tensor<6x6xf32>
  }
}
