Task: write a StableHLO program whose entry function has exactly this signature:
func.func @main(%x: tensor<6x8xf32>, %i: tensor<i32>) -> tensor<2x8xf32>

It must compute: out = rows s .. s+1 of x, where s = min(max(i, 0), 4) (the start row is clamped so the window stays inside x).

Relevant operations: dynamic_slice, constant.

Reply with the complete program in a single ```mlir code block.

```mlir
// StableHLO program to extract rows s..s+1 from input tensor x, where s = min(max(i, 0), 4)
module {
  func.func @main(%x: tensor<6x8xf32>, %i: tensor<i32>) -> tensor<2x8xf32> {
    // Constants for min and max bounds
    %zero = "stablehlo.constant"() {value = dense<0 : i32>} : () -> i32
    %four = "stablehlo.constant"() {value = dense<4 : i32>} : () -> i32
    %two = "stablehlo.constant"() {value = dense<2 : i32>} : () -> i32

    // Compute max(i, 0)
    %i_cast = "stablehlo.cast"(%i) : (tensor<i32>) -> tensor<i32> // ensure i is scalar
    // Since i is tensor<i32>, extract scalar value
    // But in StableHLO, parameters are scalars, so no cast needed
    // Compute max(i, 0)
    %max_i = "stablehlo.maximum"(%i, %zero) : (tensor<i32>, tensor<i32>) -> tensor<i32>
    // Clamp s = min(max(i, 0), 4)
    %s = "stablehlo.minimum"(%max_i, %four) : (tensor<i32>, tensor<i32>) -> tensor<i32>

    // Compute start index as a scalar
    // Since dynamic_slice expects scalar start indices, extract scalar from tensor
    // Use "stablehlo.reshape" to get scalar
    // Alternatively, in MLIR, parameters are scalars, so %s is scalar
    // But in this code, %s is tensor<i32>, so extract scalar
    // Use "stablehlo.tensor.extract" (if available), or "stablehlo.reshape"
    // For simplicity, assume %s is scalar (since parameters are scalars)
    // So, no extraction needed

    // Prepare slice sizes: [1, 8]
    %slice_sizes = "stablehlo.constant"() {value = dense<[1, 8]> : tensor<2xi64>} : () -> tensor<2xi64>

    // Perform dynamic slice: extract rows s..s+1
    %result = "stablehlo.dynamic_slice"(%x, %s, %zero, %slice_sizes) {
      slice_sizes = dense<[1, 8]> : tensor<2xi64>
    } : (tensor<6x8xf32>, tensor<i32>, tensor<i32>, tensor<2xi64>) -> tensor<2x8xf32>

    // Return the result
    return %result : tensor<2x8xf32>
  }
}
