Task: write a StableHLO program whose entry function has exactly this signature:
func.func @main(%idx: tensor<4xi32>) -> tensor<4x8xf32>

It must compute: out[n, c] = 1.0 if idx[n] == c else 0.0, for c < 8; a row whose idx is outside 0..7 is all zeros.

Relevant operations: iota, broadcast_in_dim, compare, select, constant.

Reply with the complete program in a single ```mlir code block.

```mlir
// StableHLO program to produce a tensor<4x8xf32> where out[n, c] = 1.0 if idx[n] == c else 0.0
module {
  func.func @main(%idx: tensor<4xi32>) -> tensor<4x8xf32> {
    // Create an iota tensor of shape [8], values [0,1,2,3,4,5,6,7]
    %iota = "stablehlo.iota"() {iota_dimension = 0 : i64} : () -> tensor<8xi32>

    // Broadcast the iota to shape [4,8], aligning with the first dimension
    %broadcast_iota = "stablehlo.broadcast_in_dim"(%iota) {broadcast_dimensions = [1]} : (tensor<8xi32>) -> tensor<4x8xi32>

    // Expand idx to shape [4,8] for comparison
    %idx_broadcast = "stablehlo.broadcast_in_dim"(%idx) {broadcast_dimensions = [0]} : (tensor<4xi32>) -> tensor<4x8xi32>

    // Compare idx and iota for equality
    %cmp = "stablehlo.compare"(%idx_broadcast, %broadcast_iota) {comparison_direction = "EQ" : string, compare_type = "SIGNED" : string} : (tensor<4x8xi32>, tensor<4x8xi32>) -> tensor<4x8xi1>

    // Convert boolean comparison result to float (1.0 for true, 0.0 for false)
    // First, cast boolean tensor to i1 (already i1), then to f32
    // Use "stablehlo.convert" if needed, but in StableHLO, boolean to float can be done via select
    // Alternatively, create constants 1.0 and 0.0 and select
    %one = "stablehlo.constant"() {value = dense<1.0 : f32>} : () -> tensor<f32>
    %zero = "stablehlo.constant"() {value = dense<0.0 : f32>} : () -> tensor<f32>

    // Use select to produce the final output
    %out = "stablehlo.select"(%cmp, %one, %zero) : (tensor<4x8xi1>, tensor<f32>, tensor<f32>) -> tensor<4x8xf32>

    return %out : tensor<4x8xf32>
  }
}
```

