  func.func @main(%x: tensor<5x8xf32>, %i: tensor<i32>) -> tensor<2x8xf32> {
    // Constants for bounds
    %zero = "stablehlo.constant"() {value = dense<0 : i32>} : () -> i32
    %three = "stablehlo.constant"() {value = dense<3 : i32>} : () -> i32
    %one = "stablehlo.constant"() {value = dense<1 : i32>} : () -> i32

    // Compute max(i, 0)
    %max_i_zero = "stablehlo.maximum"(%i, %zero) : (tensor<i32>, tensor<i32>) -> tensor<i32>
    // Compute min(max(i, 0), 3)
    %s = "stablehlo.minimum"(%max_i_zero, %three) : (tensor<i32>, tensor<i32>) -> tensor<i32>

    // Convert s to i64 for slicing
    %s_i64 = "stablehlo.convert"(%s) : (tensor<i32>) -> tensor<1x i64>
    // Reshape s_i64 to 1D tensor
