// StableHLO program to normalize each row of a tensor to unit L2 norm
module {
  func.func @main(%x: tensor<4x3xf32>) -> tensor<4x3xf32> {
    // Compute x^2 element-wise
    %x_squared = "stablehlo.multiply"(%x, %x) : (tensor<4x3xf32>, tensor<4x3xf32>) -> tensor<4x3xf32>

    // Reduce along dimension 1 (columns) to sum squares per row
    %init_sum = "stablehlo.constant"() {value = dense<0.0 : f32>} : () -> tensor<f32>
    %sum_squares = "stablehlo.reduce"(%x_squared, %init_sum) ({
      ^bb0(%a: tensor<f32>, %b: tensor<f32>):
        %s = "stablehlo.add"(%a, %b) : (tensor<f32>, tensor<f32>) -> tensor<f32>
        "stablehlo.return"(%s) : (tensor<f32>) -> ()
    }) {dimensions = array<i64: 1>} : (tensor<4x3xf32>, tensor<f32>) -> tensor<4xf32>

    // Broadcast sum to shape [4,3] for division
    %sum_broadcast = "stablehlo.broadcast_in_dim"(%sum_squares) {
      broadcast_dimensions = array<i64: 1>
    } : (tensor<4xf32>) -> tensor<4x3xf32>

    // Compute sqrt of sum of squares
    %norms = "stablehlo.sqrt"(%sum_broadcast) : (tensor<4x3xf32>) -> tensor<4x3xf32>

    // To avoid division by zero, add a small epsilon
    %epsilon = "stablehlo.constant"() {value = dense<1e-6 : f32>} : () -> tensor<f32>
    %norms_safe = "stablehlo.maximum"(%norms, %epsilon) : (tensor<4x3xf32>, tensor<f32>) -> tensor<4x3xf32>

    // Divide original x by norms
    %out = "stablehlo.divide"(%x, %norms_safe) : (tensor<4x3xf32>, tensor<4x3xf32>) -> tensor<4x3xf32>

    return %out : tensor<4x3xf32>
  }
}
