Relevant operations: reduce, broadcast_in_dim, element-wise ops (add/subtract/multiply/divide/maximum/minimum/negate/exponential/sqrt/rsqrt/abs), constant.

Reply with the complete program in a single ```mlir code block.

```mlir
// StableHLO program to normalize each row of a 3x8 tensor to unit L2 norm
module {
  func.func @main(%x: tensor<3x8xf32>) -> tensor<3x8xf32> {
    // Step 1: Compute x^2 element-wise
    %x_squared = "stablehlo.multiply" %x, %x : tensor<3x8xf32>

    // Step 2: Reduce along the last dimension (k) to sum squares
    %init_zero = "stablehlo.constant"() {value = dense<0.0 : f32>} : () -> f32
    %sum_squares = "stablehlo.reduce"(%x_squared, %init_zero) {
      ^bb0(%a: tensor<8xf32>, %b: tensor<8xf32>) {
        %sum = "stablehlo.add" %a, %b : tensor<8xf32>
        "stablehlo.return" %sum : tensor<8xf32>
      }
    } {dimensions = [1]} : (tensor<3x8xf32>, f32) -> tensor<3xf32>

    // Step 3: Broadcast the sum to match shape for division
    // sum shape: [3], need to broadcast to [3,8]
    %sum_broadcast_dims = array<i64: 1> // broadcast along dimension 1
    %sum_broadcast = "stablehlo.broadcast_in_dim" %sum_squares {broadcast_dimensions = [1]} : tensor<3xf32> -> tensor<3x8xf32>

    // Step 4: Compute sqrt of sum of squares
    %norms = "stablehlo.sqrt" %sum_broadcast : tensor<3x8xf32>

    // Step 5: Divide each element by the row norm
    %out = "stablehlo.divide" %x, %norms : tensor<3x8xf32>

    return %out : tensor<3x8xf32>
  }
}
