  // But in StableHLO, permutation is an attribute: array<i64: ...>
  // We want permutation [1, 0, 2]
  %permutation = affine_map<(i64, i64, i64) -> (i64, i64, i64)> {doms = [0, 1, 2], ranges = [0, 1, 2], results = [1, 0, 2]}
  // Actually, in StableHLO, permutation is an attribute array<i64: ...>
