  %perm_attr = array<i64: 1, 0, 2>
  %transposed = "stablehlo.transpose"(%reshaped) {permutation = %perm_attr} : (tensor<2x3x4xf32>) -> tensor<3x2x4xf32>

  return %transposed : tensor<3x2x4xf32>
