// StableHLO program to normalize each row of a 4x3 tensor to unit L2 norm
module {
  func.func @main(%x: tensor<4x3xf32>) -> tensor<4x3xf32> {
    // Step 1: Compute x^2 element-wise
    %x_squared = "stablehlo.multiply" %x, %x : tensor<4x3xf32>

    // Step 2: Sum over the last dimension (k) to get sum_k x[i,k]^2 for each row
    %init_sum = "stablehlo.constant"() {value = dense<0.0> : tensor<f32>} : () -> tensor<4xf32>
    %sum_squared = "stablehlo.reduce"(%x_squared, %init_sum) {
      ^bb0(%a: tensor<f32>, %b: tensor<f32>):
        %s = "stablehlo.add" %a, %b : tensor<f32>
        "stablehlo.return" %s : (tensor<f32>) -> ()
    } {dimensions = array<i64: 1>} : (tensor<4x3xf32>, tensor<4xf32>) -> tensor<4xf32>

    // Step 3: Compute sqrt of the sum to get the L2 norm per row
    %l2_norm = "stablehlo.sqrt" %sum_squared : tensor<4xf32>

    // Step 4: Broadcast the L2 norm to match the shape of x for division
    %broadcast_dims = array<i64: 1>
    %l2_norm_broadcasted = "stablehlo.broadcast_in_dim" %l2_norm {broadcast_dimensions = %broadcast_dims} : (tensor<4xf32>) -> tensor<4x3xf32>

    // Step 5: Divide each element by the corresponding row's L2 norm
    %out = "stablehlo.divide" %x, %l2_norm_broadcasted : tensor<4x3xf32>

    return %out : tensor<4x3xf32>
  }
}
