module {
  func.func @main(%x: tensor<7x8xf32>) -> tensor<7x8xf32> {
    // Step 1: Compute exp(x)
    %exp_x = "stablehlo.exponential"(%x) : (tensor<7x8xf32>) -> tensor<7x8xf32>

    // Step 2: Compute sum_k exp(x[i, k]) for each row (dimension 1)
    // Initialize zero tensor for reduction
    %zero = "stablehlo.constant"() {value = dense<0.0> : tensor<f32>} : () -> tensor<f32>
    // Reduce over dimension 1 (columns)
    %sum_exp = "stablehlo.reduce"(%exp_x, %zero) ({
      ^bb0(%a: tensor<f32>, %b: tensor<f32>):
        %s = "stablehlo.add"(%a, %b) : (tensor<f32>, tensor<f32>) -> tensor<f32>
        "stablehlo.return"(%s) : (tensor<f32>) -> ()
    }) {dimensions = array<i64: 1>} : (tensor<7x8xf32>, tensor<f32>) -> tensor<7x1xf32>

    // Step 3: Broadcast sum back to shape of exp_x for division
    %broadcast_dims = array<i64: 1>
    %sum_exp_broadcast = "stablehlo.broadcast_in_dim"(%sum_exp) {broadcast_dimensions = %broadcast_dims} : (tensor<7x1xf32>) -> tensor<7x8xf32>

    // Step 4: Compute softmax numerator: exp_x / sum_exp_broadcast
    %softmax_numerator = "stablehlo.divide"(%exp_x, %sum_exp_broadcast) : (tensor<7x8xf32>, tensor<7x8xf32>) -> tensor<7x8xf32>

    // Output the result
    "stablehlo.return"(%softmax_numerator) : (tensor<7x8xf32>) -> ()
  }
}
