```mlir
// StableHLO program to compute a lower triangular mask on a 5x5 tensor
module {
  func.func @main(%x: tensor<5x5xf32>) -> tensor<5x5xf32> {
    // Generate row indices: shape [5]
    %rows = "stablehlo.iota"() {iota_dimension = 0 : i64} : () -> tensor<5xi64>
    // Generate column indices: shape [5]
    %cols = "stablehlo.iota"() {iota_dimension = 1 : i64} : () -> tensor<5xi64>
    // Broadcast row indices to shape [5,5]
    %rows_bcast = "stablehlo.broadcast_in_dim"(%rows) {
      broadcast_dimensions = dense<[0]> : tensor<1xi64>
    } : (tensor<5xi64>) -> tensor<5x5xi64>
    // Broadcast column indices to shape [5,5]
    %cols_bcast = "stablehlo.broadcast_in_dim"(%cols) {
      broadcast_dimensions = dense<[1]> : tensor<1xi64>
    } : (tensor<5xi64>) -> tensor<5x5xi64>
    // Compare if column index <= row index
    %cmp = "stablehlo.compare"(%cols_bcast, %rows_bcast) {
      comparison_direction = #stablehlo<"LE">,
      compare_type = #stablehlo<"TOTAL_ORDER">
    } : (tensor<5x5xi64>, tensor<5x5xi64>) -> tensor<5x5xi1>
    // Convert comparison result from i1 to f32
    %mask_f32 = "stablehlo.convert"(%cmp) {
      to_element_type = f32
    } : (tensor<5x5xi1>) -> tensor<5x5xf32>
    // Create a constant zero tensor of shape [5,5]
    %zero = "stablehlo.constant"() {value = dense<0.0 : f32>} : () -> tensor<5x5xf32>
    // Select elements from x or zero based on mask
    %result = "stablehlo.select"(%mask_f32, %x, %zero) : (tensor<5x5xf32>, tensor<5x5xf32>) -> tensor<5x5xf32>
    return %result : tensor<5x5xf32>
  }
}
