module {
  func.func @main(%x: tensor<4x8xf32>) -> tensor<4x8xf32> {
    // Compute exp(x)
    %exp_x = "stablehlo.exponential"(%x) : (tensor<4x8xf32>) -> tensor<4x8xf32>

    // Reduce exp_x over dimension 1 (columns) to compute sum_k exp(x[i, k])
    %init_sum = "stablehlo.constant"() : () -> tensor<8xf32>
    %sum_exp = "stablehlo.reduce"(%exp_x, %init_sum) ({
      ^bb0(%a: tensor<8xf32>, %b: tensor<8xf32>):
        %sum = "stablehlo.add"(%a, %b) : (tensor<8xf32>, tensor<8xf32>) -> tensor<8xf32>
        "stablehlo.return"(%sum) : (tensor<8xf32>) -> ()
    }) : (tensor<4x8xf32>, tensor<8xf32>) -> tensor<4x8xf32> {
      dimensions = [1]
    }

    // Broadcast sum_k exp(x[i, k]) back to shape [4,8]
    %broadcast_sum = "stablehlo.broadcast_in_dim"(%sum_exp) {
      broadcast_dimensions = [0, 1]
    } : (tensor<4x8xf32>) -> tensor<4x8xf32>

    // Compute softmax numerator: exp(x)
    // Divide exp(x) by sum_k exp(x[i, k])
    %softmax = "stablehlo.divide"(%exp_x, %broadcast_sum) : (tensor<4x8xf32>, tensor<4x8xf32>) -> tensor<4x8xf32>

    return %softmax : tensor<4x8xf32>
  }
}
