```mlir
// StableHLO program to compute a lower triangular mask and apply it to input tensor
module {
  func.func @main(%x: tensor<3x3xf32>) -> tensor<3x3xf32> {
    // Generate row indices: iota with dimension 0 (rows)
    %rows = "stablehlo.iota"() {iota_dimension = 0 : i64} : () -> tensor<3x1xi64>
    // Generate column indices: iota with dimension 1 (columns)
    %cols = "stablehlo.iota"() {iota_dimension = 1 : i64} : () -> tensor<1x3xi64>
    // Broadcast row indices to shape 3x3
    %rows_bcast = "stablehlo.broadcast_in_dim"(%rows) {
      broadcast_dimensions = dense<i64: 0>
    } : (tensor<3x1xi64>) -> tensor<3x3xi64>
    // Broadcast column indices to shape 3x3
    %cols_bcast = "stablehlo.broadcast_in_dim"(%cols) {
      broadcast_dimensions = dense<i64: 1>
    } : (tensor<1x3xi64>) -> tensor<3x3xi64>
    // Compare row indices and column indices: row <= col
    %cmp = "stablehlo.compare"(%rows_bcast, %cols_bcast) {
      comparison_direction = #stablehlo<comparison_direction "LE">,
      compare_type = #stablehlo<compare_type "TOTAL_ORDER">
    } : (tensor<3x3xi64>, tensor<3x3xi64>) -> tensor<3x3xi1>
    // Convert comparison result to float32 mask: 1.0 for true, 0.0 for false
    %mask_int = "stablehlo.convert"(%cmp) {
      to_type = tensor<3x3xi32>
    } : (tensor<3x3xi1>) -> tensor<3x3xi32>
    %mask_float = "stablehlo.convert"(%mask_int) {
      to_type = tensor<3x3xf32>
    } : (tensor<3x3xi32>) -> tensor<3x3xf32>
    // Create constant 0.0 tensor
    %zero = "stablehlo.constant"() {value = dense<0.0> : tensor<f32>} : () -> tensor<f32>
    // Select elements: if mask == 1.0, take x; else 0.0
    %out = "stablehlo.select"(%mask_float, %x, %zero) : (tensor<3x3xf32>, tensor<3x3xf32>, tensor<3x3xf32>) -> tensor<3x3xf32>
    return %out : tensor<3x3xf32>
  }
}
