// StableHLO program to compute the mean over dimension 1 of a tensor<7x4xf32>
module {
  func.func @main(%x: tensor<7x4xf32>) -> tensor<7xf32> {
    // Step 1: Create a constant tensor of 1.0 of shape [4]
    %one = "stablehlo.constant"() {value = dense<1.0> : tensor<4xf32>} : () -> tensor<4xf32>

    // Step 2: Broadcast the scalar 1.0 to shape [7,4] to match input shape
    // Since StableHLO does not have explicit broadcast, we can use "stablehlo.broadcast_in_dim"
    // with the appropriate dimensions.
    %broadcast_dims = "stablehlo.constant"() {value = dense<[0, 1]> : tensor<2xi64>} : () -> tensor<2xi64>
    %bcast_one = "stablehlo.broadcast_in_dim"(%one, %x) {
      broadcast_dimensions = %broadcast_dims
    } : (tensor<4xf32>, tensor<7x4xf32>) -> tensor<7x4xf32>

    // Step 3: Sum over dimension 1
    %sum = "stablehlo.reduce"(%x, %zero) ({
      ^bb0(%a: tensor<7x4xf32>, %b: tensor<7x4xf32>): tensor<7x4xf32> {
        %s = "stablehlo.add"(%a, %b) : (tensor<7x4xf32>, tensor<7x4xf32>) -> tensor<7x4xf32>
        "stablehlo.return"(%s) : (tensor<7x4xf32>) -> ()
      }
    }) {dimensions = array<i64: 1>} : (tensor<7x4xf32>, tensor<f32>) -> tensor<7x4xf32>

    // Step 4: Sum of ones over dimension 1 to compute count
    %count = "stablehlo.reduce"(%bcast_one, %zero) ({
      ^bb0(%a: tensor<7x4xf32>, %b: tensor<7x4xf32>): tensor<7x4xf32> {
        %s = "stablehlo.add"(%a, %b) : (tensor<7x4xf32>, tensor<7x4xf32>) -> tensor<7x4xf32>
        "stablehlo.return"(%s) : (tensor<7x4xf32>) -> ()
      }
    }) {dimensions = array<i64: 1>} : (tensor<7x4xf32>, tensor<f32>) -> tensor<7x4xf32>

    // Step 5: Divide sum by count to get mean
    %mean = "stablehlo.divide"(%sum, %count) : (tensor<7x4xf32>, tensor<7x4xf32>) -> tensor<7x4xf32>

    // Step 6: Reduce mean over dimension 1 to get shape [7]
    %result = "stablehlo.reduce"(%mean, %zero) ({
      ^bb0(%a: tensor<7x4xf32>, %b: tensor<f32>): tensor<7x4xf32> {
        %s = "stablehlo.add"(%a, %b) : (tensor<7x4xf32>, tensor<f32>) -> tensor<7x4xf32>
        "stablehlo.return"(%s) : (tensor<7x4xf32>) -> ()
      }
    }) {dimensions = array<i64: 1>} : (tensor<7x4xf32>, tensor<f32>) -> tensor<7x4xf32>

    // Step 7: Divide each row by 4 to get the mean
    %div_const = "stablehlo.constant"() {value = dense<4.0> : tensor<f32>} : () -> tensor<f32>
    // Broadcast scalar 4.0 to shape [7]
    %bcast_four = "stablehlo.broadcast_in_dim"(%div_const, %result) {
