    %final = "stablehlo.divide"(%result, %bcast_four) : (tensor<7>, tensor<7>) -> tensor<7xf32>

    // Return the final tensor
    return %final : tensor<7xf32>
  }

  // Define the zero constant for reduction
  %zero = "stablehlo.constant"() {value = dense<0.0> : tensor<f32>} : () -> tensor<f32>
