// StableHLO program implementing softmax over dimension 1
module {
  func.func @main(%x: tensor<4x5xf32>) -> tensor<4x5xf32> {
    // Step 1: Compute exp(x)
    %exp_x = "stablehlo.exponential"(%x) : (tensor<4x5xf32>) -> tensor<4x5xf32>

    // Step 2: Compute sum_k exp(x[i, k]) for each row
    // Initialize zero tensor for reduction
    %zero = "stablehlo.constant"() {value = dense<0.0> : tensor<f32>} : () -> tensor<f32>
    // Reduce over dimension 1 (columns)
    %sum_exp = "stablehlo.reduce"(%exp_x, %zero) ({
      ^bb0(%a: tensor<4x5xf32>, %b: tensor<4x5xf32>): tensor<4x5xf32> {
        %s = "stablehlo.add"(%a, %b) : (tensor<4x5xf32>, tensor<4x5xf32>) -> tensor<4x5xf32>
        "stablehlo.return"(%s) : (tensor<4x5xf32>) -> ()
      }
    }) {dimensions = array<i64: 1>} : (tensor<4x5xf32>, tensor<f32>) -> tensor<4x5xf32>

    // Step 3: Broadcast sum to shape of exp_x for division
    %sum_broadcast = "stablehlo.broadcast_in_dim"(%sum_exp) {broadcast_dimensions = array<i64: 1>} : (tensor<4x5xf32>) -> tensor<4x5xf32>

    // Step 4: Compute softmax numerator: exp_x / sum_broadcast
    %softmax_numerator = "stablehlo.divide"(%exp_x, %sum_broadcast) : (tensor<4x5xf32>, tensor<4x5xf32>) -> tensor<4x5xf32>

    // Output the result
    return %softmax_numerator : tensor<4x5xf32>
  }
}
