module {
  func.func @main(%x: tensor<8x7xf32>) -> tensor<8xi32> {
    // Step 1: Create a constant tensor of zeros for comparison
    %zero = "stablehlo.constant"() {value = dense<0.0> : tensor<f32>} : () -> tensor<f32>

    // Step 2: Compare each element of x with zero to get a boolean tensor
    %cmp = "stablehlo.compare"(%x, %zero) {comparison_direction = "GT"} : (tensor<8x7xf32>, tensor<f32>) -> tensor<8x7x1b>

    // Step 3: Convert boolean tensor to i32 (true -> 1, false -> 0)
    %cmp_i32 = "stablehlo.convert"(%cmp) {to = "s32"} : (tensor<8x7x1b>) -> tensor<8x7x1s32>

    // Step 4: Reshape the comparison tensor to match the shape for reduction
    // The tensor is already shape <8x7x1s32>, but we want to reduce over the last dimension
    // So, no reshape needed; reduction will be over dimension 1 (the j dimension)

    // Step 5: Reduce over the second dimension (j) to sum the counts per row
    %result = "stablehlo.reduce"(%cmp_i32, %zero) {
      dimensions = dense<1> : tensor<1>,
      reduction_kind = "ADD"
    } : (tensor<8x7x1s32>, tensor<8x7x1s32>) -> tensor<8x1s32>

    // Step 6: Squeeze the last dimension to get shape <8>
    %result_squeezed = "stablehlo.collapse_shape"(%result) {
      shape = tensor<8xi32>
    } : (tensor<8x1s32>) -> tensor<8xi32>

    // Step 7: Return the result
    return %result_squeezed : tensor<8xi32>
  }
}
