module {
  func.func @main(%idx: tensor<8xi32>) -> tensor<8x3xf32> {
    // Create an iota tensor of shape [8], values [0,1,2,3,4,5,6,7]
    %iota = "stablehlo.iota"() : () -> tensor<8xi64>

    // Broadcast iota to shape [8, 3], along dimension 1
    %broadcast_iota = "stablehlo.broadcast_in_dim"(%iota) {broadcast_dimensions = [0]} : (tensor<8xi64>) -> tensor<8x3xi64>

    // Create a tensor of shape [3], values [0,1,2]
    %c_values = "stablehlo.iota"() : () -> tensor<3xi64>

    // Broadcast c_values to shape [8, 3]
    %broadcast_c = "stablehlo.broadcast_in_dim"(%c_values) {broadcast_dimensions = [0]} : (tensor<3xi64>) -> tensor<8x3xi64>

    // Compare idx with broadcasted c to get a boolean tensor
    %cmp = "stablehlo.compare"(%broadcast_iota, %broadcast_c) {comparison_direction = #stablehlo<"EQ">, compare_type = #stablehlo<"INT64">} : (tensor<8x3xi64>, tensor<8x3xi64>) -> tensor<8x3xi1>

    // Convert boolean comparison result to float: 1.0 for true, 0.0 for false
    %cmp_float = "stablehlo.convert"(%cmp) : (tensor<8x3xi1>) -> tensor<8x3xf32>

    // Create a constant tensor of 1.0
    %one = "stablehlo.constant"() {value = dense<1.0> : tensor<f32>} : () -> tensor<f32>

    // Create a mask tensor of zeros for positions where idx outside 0..2
    // For positions where comparison is false, set 0.0; for true, 1.0
    // But since comparison is only true when idx == c, and c in 0..2, the comparison result is already zero for outside 0..2
    // So, we can directly multiply cmp_float with 1.0 to get the desired output
    // For positions outside 0..2, cmp_float is 0.0, so output is 0.0
    // For positions where idx == c (c in 0..2), cmp_float is 1.0, so output is 1.0
    %result = "stablehlo.multiply"(%cmp_float, %one) : (tensor<8x3xf32>, tensor<f32>) -> tensor<8x3xf32>

    return %result : tensor<8x3xf32>
  }
