// StableHLO program to compute pairwise squared Euclidean distances between rows of x and y
module {
  func.func @main(%x: tensor<3x5xf32>, %y: tensor<6x5xf32>) -> tensor<3x6xf32> {
    // Step 1: Broadcast x to shape [3, 6, 5]
    %x_bcast = "stablehlo.broadcast_in_dim"(%x) {broadcast_dimensions = array<i64: 1>} : (tensor<3x5xf32>) -> tensor<3x6x5xf32>
    // Step 2: Broadcast y to shape [3, 6, 5]
    %y_bcast = "stablehlo.broadcast_in_dim"(%y) {broadcast_dimensions = array<i64: 0>} : (tensor<6x5xf32>) -> tensor<6x5x1>
    // To match dimensions, we need to reshape y to [1, 6, 5], then broadcast
    // But since y is [6,5], broadcast to [3,6,5] by adding a leading dimension
    // So, broadcast y to shape [3,6,5]
    %y_bcast2 = "stablehlo.broadcast_in_dim"(%y) {broadcast_dimensions = array<i64: 0>} : (tensor<6x5xf32>) -> tensor<3x6x5>
    // Actually, better to broadcast y to shape [3,6,5] by adding a leading dimension
    // So, first reshape y to [1,6,5]
    // But in StableHLO, we can broadcast directly
    // Let's do a reshape of y to [1,6,5]
    %y_reshaped = "stablehlo.reshape"(%y) {shape = array<i64: 1, 6, 5>} : (tensor<6x5xf32>) -> tensor<1x6x5xf32>
    // Now broadcast y to [3,6,5]
    %y_bcast_final = "stablehlo.broadcast_in_dim"(%y_reshaped) {broadcast_dimensions = array<i64: 0, 1, 2>} : (tensor<1x6x5xf32>) -> tensor<3x6x5xf32>
    // Step 3: Compute difference: diff = x_bcast - y_bcast_final
    %diff = "stablehlo.subtract"(%x_bcast, %y_bcast_final) : (tensor<3x6x5xf32>, tensor<3x6x5xf32>) -> tensor<3x6x5xf32>
    // Step 4: Square the difference: diff_squared = diff * diff
    %diff_squared = "stablehlo.multiply"(%diff, %diff) : (tensor<3x6x5xf32>, tensor<3x6x5xf32>) -> tensor<3x6x5xf32>
    // Step 5: Sum over the last dimension (dimension 2) to get squared distances
    // Initialize reduction with zero
    %zero = "stablehlo.constant"() {value = dense<0.0> : tensor<f32>} : () -> tensor<f32>
    // Define reduction body
    func @reduce_body(%a: tensor<f32>, %b: tensor<f32>) -> (tensor<f32>) {
      %s = "stablehlo.add"(%a, %b) : (tensor<f32>, tensor<f32>) -> tensor<f32>
      "stablehlo.return"(%s) : (tensor<f32>) -> ()
    }
    // Perform reduction over dimension 2
    %distances = "stablehlo.reduce"(%diff_squared, %zero) {
      ^bb0(%a: tensor<f32>, %b: tensor<f32>) -> (tensor<f32>) {
        %s = "stablehlo.add"(%a, %b) : (tensor<f32>, tensor<f32>) -> tensor<f32>
        "stablehlo.return"(%s) : (tensor<f32>) -> ()
      }
    } : (tensor<3x6x5xf32>, tensor<f32>) -> tensor<3x6xf32> {
      dimensions = array<i64: 2>
    }
    // Return the result
    return %distances : tensor<3x6xf32>
  }
}
