// StableHLO program to compute the mean over dimension 1 of a tensor<6x4xf32>
module {
  func.func @main(%x: tensor<6x4xf32>) -> tensor<6xf32> {
    // Step 1: Create a constant tensor of shape [4] with all elements = 1.0
    %one_const = "stablehlo.constant"() {value = dense<1.0> : tensor<4xf32>} : () -> tensor<4xf32>

    // Step 2: Reduce the input tensor along dimension 1 (the second dimension)
    // The reduction body adds two scalar tensors
    %init = "stablehlo.constant"() {value = dense<0.0> : tensor<f32>} : () -> tensor<f32>
    %reduced = "stablehlo.reduce"(%x, %init) ({
      ^bb0(%a: tensor<f32>, %b: tensor<f32>):
        %sum = "stablehlo.add"(%a, %b) : (tensor<f32>, tensor<f32>) -> tensor<f32>
        "stablehlo.return"(%sum) : (tensor<f32>) -> ()
    }) {dimensions = array<i64: 1>} : (tensor<6x4xf32>, tensor<f32>) -> tensor<6x4xf32>

    // Step 3: Broadcast the constant [4] to match the shape of the reduced tensor (shape: [6])
    // Since the reduced tensor shape is [6], we need to broadcast %one_const to shape [6]
    // But first, we need to reshape %one_const to shape [4], then broadcast to [6]
    // Actually, for division, we need to divide each sum by 4, so we can broadcast scalar 4.0 to shape [6]
    // Alternatively, create a tensor of shape [6] filled with 4.0
    // But since the reduction sums over dimension 1, the shape of %reduced is [6]
    // So, create a scalar 4.0 and broadcast to shape [6]
    // Let's create a scalar constant 4.0
    %four_const = "stablehlo.constant"() {value = dense<4.0> : tensor<f32>} : () -> tensor<f32>
    // Broadcast scalar 4.0 to shape [6]
    %broadcast_divisor = "stablehlo.broadcast_in_dim"(%four_const) {
      broadcast_dimensions = array<i64: 0>
    } : (tensor<f32>) -> tensor<6xf32>

    // Step 4: Divide the sum by 4 to get the mean
    %mean = "stablehlo.divide"(%reduced, %broadcast_divisor) : (tensor<6xf32>, tensor<6xf32>) -> tensor<6xf32>

    // Return the result
    return %mean : tensor<6xf32>
  }
}
