  func.func @main(%x: tensor<5x5xf32>) -> tensor<5x5xf32> {
    // Generate row indices (iota along dimension 0)
    %rows = "stablehlo.iota"() {iota_dimension = 0 : i64} : () -> tensor<5x5xf32>
    // Generate column indices (iota along dimension 1)
    %cols = "stablehlo.iota"() {iota_dimension = 1 : i64} : () -> tensor<5x5xf32>
    // Convert row indices to i32 for comparison
    %rows_i32 = "stablehlo.convert"(%rows) : (tensor<5x5xf32>) -> tensor<5x5xi32>
    // Convert column indices to i32 for comparison
    %cols_i32 = "stablehlo.convert"(%cols) : (tensor<5x5xf32>) -> tensor<5x5xi32>
    // Compare if column index <= row index
    %cmp = "stablehlo.compare"(%cols_i32, %rows_i32) {
      comparison_direction = "LE" : #stablehlo<comparison_direction>,
      compare_type = "SIGNED" : #stablehlo<compare_type>
    } : (tensor<5x5xi32>, tensor<5x5xi32>) -> tensor<5x5xi1>
    // Create a zero constant tensor of shape 5x5
    %zero_const = "stablehlo.constant"() {value = dense<0.0 : f32>} : () -> tensor<5x5xf32>
    // Use select to choose between x and zero based on comparison
    %result = "stablehlo.select"(%cmp, %x, %zero_const) : (tensor<5x5xi1>, tensor<5x5xf32>, tensor<5x5xf32>) -> tensor<5x5xf32>
    return %result : tensor<5x5xf32>
  }
}
