module {
  func.func @main(%x: tensor<4x3xf32>) -> tensor<4x3xf32> {
    // Step 1: Compute x^2 element-wise
    %x_squared = "stablehlo.multiply" %x, %x : tensor<4x3xf32>

    // Step 2: Reduce along the last dimension (k) to sum squares per row
    %init_sum = "stablehlo.constant"() {value = dense<0.0 : f32>} : () -> tensor<4xf32>
    %sum_squares = "stablehlo.reduce" %x_squared, %init_sum
