      {dimensions = array<i64: 1>} : (tensor<4x3xf32>, tensor<4xf32>) -> tensor<4xf32>

    // Step 3: Compute sqrt of sum of squares to get L2 norm per row
    %l2_norm = "stablehlo.sqrt" %sum_squares : tensor<4xf32>

    // Step 4: Broadcast the L2 norm to match shape of x (4x3)
    %bcast_norm = "stablehlo.broadcast_in_dim" %l2_norm {broadcast_dimensions = array<i64: 0>} : (tensor<4xf32>) -> tensor<4x3xf32>

    // Step 5: Divide each element by its row's L2 norm
    %out = "stablehlo.divide" %x, %bcast_norm : tensor<4x3xf32>

    return %out : tensor<4x3xf32>
  }
}
