module {
  func.func @main(%x: tensor<2x3x4xf32>, %s: tensor<2x4xf32>) -> tensor<2x3x4xf32> {
    // Get the shape dimensions
    %dim0 = "stablehlo.constant"() {value = dense_int_attr<i64>({0})} : () -> i64
    %dim1 = "stablehlo.constant"() {value = dense_int_attr<i64>({1})} : () -> i64
    %dim2 = "stablehlo.constant"() {value = dense_int_attr<i64>({2})} : () -> i64
    %dim3 = "stablehlo.constant"() {value = dense_int_attr<i64>({3})} : () -> i64

    // Broadcast s[a, c] to shape [2, 3, 4]
    // First, extract s[a, c]
    // For broadcasting, we need to add singleton dimensions
    // s has shape [2, 4], need to broadcast to [2, 3, 4]
    // So, broadcast s with broadcast_dimensions = [0, 1], adding singleton dimension at position 1
    // But since s is [2,4], to match [2,3,4], we broadcast s to shape [2,1,4], then broadcast to [2,3,4]
    // Alternatively, directly broadcast s with broadcast_dimensions = [0, 1], but need to reshape s first

    // Reshape s to [2, 1, 4]
    %s_reshaped = "stablehlo.reshape"(%s) {shape = dense_int_attr<i64>({2, 1, 4})} : (tensor<2x4xf32>) -> tensor<2x1x4xf32>

    // Broadcast s_reshaped to [2, 3, 4]
    %s_broadcasted = "stablehlo.broadcast_in_dim"(%s_reshaped) {
      broadcast_dimensions = array<i64: 0, 2>,
      shape = dense_int_attr<i64>({2, 3, 4})
    } : (tensor<2x1x4xf32>) -> tensor<2x3x4xf32>

    // Now, perform element-wise multiplication: x * s_broadcasted
    %out = "stablehlo.multiply"(%x, %s_broadcasted) : (tensor<2x3x4xf32>, tensor<2x3x4xf32>) -> tensor<2x3x4xf32>

    // Return the result
    return %out : tensor<2x3x4xf32>
  }
