    %axes = constant dense<[1]> : tensor<1> // dimension to reduce
    %count = reduce "add" %mask_int, %c0_i32 {dimensions = %axes} : tensor<8x3xi32>, tensor<8xi32>

    return %count : tensor<8xi32>
  }
}
