// StableHLO program implementing softmax over dimension 1
module {
  func.func @main(%x: tensor<4x5xf32>) -> tensor<4x5xf32> {
    // Step 1: Compute exp(x)
    %exp_x = "stablehlo.exponential"(%x) : (tensor<4x5xf32>) -> tensor<4x5xf32>

    // Step 2: Compute sum_k exp(x[i, k]) for each i
    // Initialize the reduction with zero
    %zero = "stablehlo.constant"() {value = dense<0.0 : f32>} : () -> tensor<f32>
    // Reduce over dimension 1 (columns)
    %sum_exp = "stablehlo.reduce"(%exp_x, %zero) ({
      ^bb0(%a: tensor<f32>, %b: tensor<f32>):
        %s = "stablehlo.add"(%a, %b) : (tensor<f32>, tensor<f32>) -> tensor<f32>
        "stablehlo.return"(%s) : (tensor<f32>) -> ()
    }) {dimensions = array<i64: 1>} : (tensor<4x5xf32>, tensor<f32>) -> tensor<4xf32>

    // Step 3: Broadcast sum back to shape of x for division
    // broadcast sum over dimension 1 to shape 4x5
    %bcast_sum = "stablehlo.broadcast_in_dim"(%sum_exp) {broadcast_dimensions = array<i64: 1>} : (tensor<4xf32>) -> tensor<4x5xf32>

    // Step 4: Compute softmax: exp(x) / sum_k exp(x[i, k])
    %softmax = "stablehlo.divide"(%exp_x, %bcast_sum) : (tensor<4x5xf32>, tensor<4x5xf32>) -> tensor<4x5xf32>

    return %softmax : tensor<4x5xf32>
  }
}
