```mlir
// StableHLO program to compute softmax over dimension 1 of a tensor<7x8xf32>
module {
  func.func @main(%x: tensor<7x8xf32>) -> tensor<7x8xf32> {
    // Step 1: Compute exp(x)
    %exp_x = "stablehlo.exponential"(%x) : (tensor<7x8xf32>) -> tensor<7x8xf32>

    // Step 2: Compute sum_k exp(x[i, k]) for each row i
    // Initialize the reduction with 0.0
    %zero = "stablehlo.constant"() {value = dense<0.0> : tensor<f32>} : () -> tensor<f32>
    // axes = [1], sum over columns
    %axes = "stablehlo.constant"() {value = dense<[1]> : tensor<1xi64>} : () -> tensor<1xi64>
    %sum_exp = "stablehlo.reduce"(%exp_x, %zero) ({
      ^bb0(%a: tensor<f32>, %b: tensor<f32>):
        "stablehlo.add"(%a, %b) : (tensor<f32>, tensor<f32>) -> tensor<f32>
    }) {dimensions = [1]} : (tensor<7x8xf32>, tensor<f32>) -> tensor<7x1xf32>

    // Step 3: Broadcast sum back to shape of x for division
    // broadcast_dimensions = [1], to align sum with dimension 1
    %bcast_sum = "stablehlo.broadcast_in_dim"(%sum_exp) {broadcast_dimensions = [1]} : (tensor<7x1xf32>) -> tensor<7x8xf32>

    // Step 4: Compute softmax: exp(x) / sum_k exp(x[i, k])
    %softmax = "stablehlo.divide"(%exp_x, %bcast_sum) : (tensor<7x8xf32>, tensor<7x8xf32>) -> tensor<7x8xf32>

    return %softmax : tensor<7x8xf32>
  }
}
