Task: write a StableHLO program whose entry function has exactly this signature:
func.func @main(%x: tensor<3x3xf32>) -> tensor<3x3xf32>

It must compute: out[i, j] = x[i, j] if j <= i, otherwise 0.0 (keep the lower triangle including the diagonal).

Relevant operations: iota, compare, select, constant.

Reply with the complete program in a single ```mlir code block.

```mlir
// StableHLO program to produce a lower triangular matrix with the input tensor
// Elements above the diagonal are set to 0.0, others are kept from input.

module {
  func.func @main(%x: tensor<3x3xf32>) -> tensor<3x3xf32> {
    // Generate row indices: iota along dimension 0
    %rows = "stablehlo.iota"() {iota_dimension = 0 : i64} : () -> tensor<3xf32>
    // Generate column indices: iota along dimension 1
    %cols = "stablehlo.iota"() {iota_dimension = 1 : i64} : () -> tensor<3xf32>

    // Convert indices to i64 for comparison
    %rows_i64 = "stablehlo.convert"(%rows) : (tensor<3xf32>) -> tensor<3xi64>
    %cols_i64 = "stablehlo.convert"(%cols) : (tensor<3xf32>) -> tensor<3xi64>

    // Expand row indices to match shape for broadcasting
    %rows_broadcasted = "stablehlo.broadcast_in_dim"(%rows_i64) {
      broadcast_dimensions = dense<[0]> : tensor<1xi64>
    } : (tensor<3xi64>) -> tensor<3x3xi64>

    // Expand column indices to match shape for broadcasting
    %cols_broadcasted = "stablehlo.broadcast_in_dim"(%cols_i64) {
      broadcast_dimensions = dense<[1]> : tensor<1xi64>
    } : (tensor<3xi64>) -> tensor<3x3xi64>

    // Compare: j <= i
    %cmp = "stablehlo.compare"(%cols_broadcasted, %rows_broadcasted) {
      comparison_direction = "LE" : "stablehlo.comparison_direction",
      compare_type = "SIGNED" : "stablehlo.compare_type"
    } : (tensor<3x3xi64>, tensor<3x3xi64>) -> tensor<3x3xi1>

    // Create a constant 0.0 tensor for filling above diagonal
    %zero = "stablehlo.constant"() {value = dense<0.0> : tensor<1xf32>} : () -> tensor<1xf32>
    // Broadcast zero to shape 3x3
    %zero_broadcasted = "stablehlo.broadcast_in_dim"(%zero) {
      broadcast_dimensions = dense<[0,1]> : tensor<2xi64>
    } : (tensor<1xf32>) -> tensor<3x3xf32>

    // Use select to choose between input and zero based on comparison
    %result = "stablehlo.select"(%cmp, %x, %zero_broadcasted) : (tensor<3x3xi1>, tensor<3x3xf32>, tensor<3x3xf32>) -> tensor<3x3xf32>

    return %result : tensor<3x3xf32>
  }
}
