    %zero = "stablehlo.constant"() {value = dense<0> : tensor<i32>} : () -> tensor<i32>
    %four = "stablehlo.constant"() {value = dense<4> : tensor<i32>} : () -> tensor<i32>
    %two = "stablehlo.constant"() {value = dense<2> : tensor<i32>} : () -> tensor<i32>
    %one = "stablehlo.constant"() {value = dense<1> : tensor<i32>} : () -> tensor<i32>

