```mlir
// StableHLO program to compute out[a, n, b] = x[a, n, b] - v[n]
module {
  func.func @main(%x: tensor<4x3x5xf32>, %v: tensor<3xf32>) -> tensor<4x3x5xf32> {
    // Broadcast %v to shape [4,3,5] along the first and third dimensions
    %v_broadcast = "stablehlo.broadcast_in_dim"(%v) {
      broadcast_dimensions = [1]
    } : (tensor<3xf32>) -> tensor<4x3x5xf32>

    // Since broadcast_in_dim requires specifying broadcast_dimensions for each dimension,
    // we need to broadcast %v along the first and third dimensions.
    // But in this case, %v is 1D, so we broadcast along dims 0 and 2.
    // To do this, we need to first reshape %v to shape [1,3,1], then broadcast.

    // Reshape %v to [1,3,1]
    %v_reshaped = "stablehlo.reshape"(%v) {shape = [1,3,1]} : (tensor<3xf32>) -> tensor<1x3x1xf32>

    // Broadcast %v_reshaped to [4,3,5]
    %v_broadcasted = "stablehlo.broadcast_in_dim"(%v_reshaped) {
      broadcast_dimensions = [0, 1, 2]
