// StableHLO program to normalize each row of a tensor to unit L2 norm
module {
  func.func @main(%x: tensor<7x3xf32>) -> tensor<7x3xf32> {
    // Compute sum of squares along the last dimension (k)
    %squares = "stablehlo.reduce"(%x) {dimensions = dense_int_array_attr([1])} : (tensor<7x3xf32>) -> tensor<7x1xf32> {
      // Initialize the reduction with zeros
      %init = "stablehlo.constant"() {value = dense_elements_attr({0.0 : f32})} : () -> tensor<7x1xf32>
      // Lambda for reduction: sum of squares
      ^bb0(%a: tensor<7x1xf32>, %b: tensor<7x3xf32>) -> tensor<7x1xf32> {
        // Broadcast %a to shape [7x3]
        %a_bcast = "stablehlo.broadcast_in_dim"(%a) {broadcast_dimensions = dense_int_array_attr([1])} : (tensor<7x1xf32>) -> tensor<7x3xf32>
        // Element-wise square of %b
        %b_sq = "stablehlo.multiply"(%b, %b) : (tensor<7x3xf32>, tensor<7x3xf32>) -> tensor<7x3xf32>
        // Element-wise multiply of %a_bcast and %b_sq
        %a_bcast_times_b_sq = "stablehlo.multiply"(%a_bcast, %b_sq) : (tensor<7x3xf32>, tensor<7x3xf32>) -> tensor<7x3xf32>
        // Sum over last dimension (k)
        %sum_k = "stablehlo.reduce"(%a_bcast_times_b_sq) {dimensions = dense_int_array_attr([1])} : (tensor<7x3xf32>) -> tensor<7x1xf32>
        // Add to accumulator
        "stablehlo.add"(%a, %sum_k) : (tensor<7x1xf32>, tensor<7x1xf32>) -> tensor<7x1xf32>
      }
      // Initial value for reduction
      %init
    } : (tensor<7x3xf32>) -> tensor<7x1xf32>

    // Compute L2 norm: sqrt of sum of squares
    %sum_squares = "stablehlo.squeeze"(%squares) : (tensor<7x1xf32>) -> tensor<7xf32>
    %l2_norm = "stablehlo.sqrt"(%sum_squares) : (tensor<7xf32>) -> tensor<7xf32>

    // Broadcast l2_norm to shape [7,3]
    %l2_norm_bcast = "stablehlo.broadcast_in_dim"(%l2_norm) {broadcast_dimensions = dense_int_array_attr([1])} : (tensor<7xf32>) -> tensor<7x3xf32>

    // To avoid division by zero, replace zeros with ones
    %zero = "stablehlo.constant"() {value = dense_elements_attr({0.0 : f32})} : () -> tensor<1xf32>
    %one = "stablehlo.constant"() {value = dense_elements_attr({1.0 : f32})} : () -> tensor<1xf32>
    // Create mask where l2_norm_bcast == 0
    %zero_mask = "stablehlo.compare"(%l2_norm_bcast, %zero) {comparison_direction = "EQ"} : (tensor<7x3xf32>, tensor<1xf32>) -> tensor<7x3xf32>
    // Replace zeros with ones
    %l2_norm_safe = "stablehlo.select"(%zero_mask, %one, %l2_norm_bcast) : (tensor<7x3xf32>, tensor<7x3xf32>, tensor<7x3xf32>) -> tensor<7x3xf32>

    // Compute normalized output: x / l2_norm_safe
    %out = "stablehlo.divide"(%x, %l2_norm_safe) : (tensor<7x3xf32>, tensor<7x3xf32>) -> tensor<7x3xf32>

    return %out : tensor<7x3xf32>
  }
