// StableHLO program to normalize each row of a 3x8 tensor to unit L2 norm
module {
  func.func @main(%x: tensor<3x8xf32>) -> tensor<3x8xf32> {
    // Step 1: Compute x^2 element-wise
    %x_squared = "stablehlo.multiply" %x, %x : tensor<3x8xf32>

    // Step 2: Reduce along the last dimension (k) to sum squares
    %init_sum = "stablehlo.constant"() {value = dense<0.0 : tensor<f32>} : () -> tensor<f32>
    %sum_squares = "stablehlo.reduce"(%x_squared, %init_sum) ({
      ^bb0(%a: tensor<f32>, %b: tensor<f32>):
        %s = "stablehlo.add" %a, %b : tensor<f32>
        "stablehlo.return" %s : (tensor<f32>) -> ()
    }) {dimensions = array<i64: 1>} : (tensor<3x8xf32>, tensor<f32>) -> tensor<3xf32>

    // Step 3: Broadcast sum to match shape for division
    %sum_broadcast = "stablehlo.broadcast_in_dim" %sum_squares {broadcast_dimensions = array<i64: 1>} : (tensor<3xf32>) -> tensor<3x8xf32>

    // Step 4: Compute sqrt of sum for normalization
    %norm = "stablehlo.sqrt" %sum_broadcast : tensor<3x8xf32>

    // Step 5: Divide original x by norm to normalize
    %out = "stablehlo.divide" %x, %norm : tensor<3x8xf32>

    return %out : tensor<3x8xf32>
  }
}
