// StableHLO program to compute squared Euclidean distances between rows of x and y
module {
  func.func @main(%x: tensor<3x5xf32>, %y: tensor<6x5xf32>) -> tensor<3x6xf32> {
    // Step 1: Broadcast x to shape [3, 5, 6]
    %x_broadcast = "stablehlo.broadcast_in_dim"(%x) {broadcast_dimensions = [0, 1, 2]} : (tensor<3x5xf32>) -> tensor<3x5x6xf32>
    // Step 2: Broadcast y to shape [3, 6, 5]
    %y_broadcast = "stablehlo.broadcast_in_dim"(%y) {broadcast_dimensions = [1, 0, 2]} : (tensor<6x5xf32>) -> tensor<6x3x5xf32>
    // Transpose y to shape [3, 6, 5] for broadcasting
    %y_transposed = "stablehlo.transpose"(%y_broadcast) {permutation = [1, 0, 2]} : tensor<6x3x5xf32>
    // Step 3: Compute difference: x_broadcast - y_transposed
    %diff = "stablehlo.subtract"(%x_broadcast, %y_transposed) : (tensor<3x5x6xf32>, tensor<3x5x6xf32>) -> tensor<3x5x6xf32>
    // Step 4: Square the differences
    %diff_squared = "stablehlo.multiply"(%diff, %diff) : (tensor<3x5x6xf32>, tensor<3x5x6xf32>) -> tensor<3x5x6xf32>
    // Step 5: Reduce sum over dimension 1 (the feature dimension)
    %init = "stablehlo.constant"() {value = dense<0.0> : tensor<f32>} : () -> tensor<f32>
    %squared_distance = "stablehlo.reduce"(%diff_squared, %init) {dimensions = [1]} : (tensor<3x5x6xf32>, tensor<f32>) -> tensor<3x6xf32>
    // Return the result
    return %squared_distance : tensor<3x6xf32>
  }
}
