// StableHLO program to compute pairwise squared Euclidean distances between rows of x and y
module {
  func.func @main(%x: tensor<4x5xf32>, %y: tensor<2x5xf32>) -> tensor<4x2xf32> {
    // Step 1: Broadcast %x to shape [4, 1, 5]
    %x_bcast = stablehlo.broadcast_in_dim %x
      {broadcast_dimensions = dense<0> : tensor<1>, shape = tensor<3>{4,1,5>}} : tensor<4x5xf32> -> tensor<4x1x5xf32>

    // Step 2: Broadcast %y to shape [1, 2, 5]
    %y_bcast = stablehlo.broadcast_in_dim %y
      {broadcast_dimensions = dense<1> : tensor<1>, shape = tensor<3>{1,2,5>}} : tensor<2x5xf32> -> tensor<1x2x5xf32>

    // Step 3: Compute difference: diff = x_bcast - y_bcast
    %diff = stablehlo.subtract %x_bcast, %y_bcast : tensor<4x1x5xf32>, tensor<1x2x5xf32> -> tensor<4x2x5xf32>

    // Step 4: Square the differences: diff_squared = diff * diff
    %diff_squared = stablehlo.multiply %diff, %diff : tensor<4x2x5xf32>, tensor<4x2x5xf32> -> tensor<4x2x5xf32>

    // Step 5: Reduce sum over the last dimension (d=5) to get squared distances
    %reduction_dims = dense<2> : tensor<1>
    %squared_distances = stablehlo.reduce %diff_squared, %zero = constant 0.0 : f32, reduction_dimensions = %reduction_dims, reduction_computation = "add" : tensor<4x2xf32>

    // Return the result
    return %squared_distances : tensor<4x2xf32>
  }
}
