module {
  func.func @main(%x: tensor<4x8xf32>) -> tensor<4x8xf32> {
    // Step 1: Compute exp(x)
    %exp_x = "stablehlo.exponential"(%x) : (tensor<4x8xf32>) -> tensor<4x8xf32>

    // Step 2: Compute sum_k exp(x[i, k]) for each row
    // Initialize zero tensor for reduction
    %zero = "stablehlo.constant"() {value = dense<0.0> : tensor<f32>} : () -> tensor<f32>
    // Reduce over dimension 1 (columns)
    %sum_exp = "stablehlo.reduce"(%exp_x, %zero) ({
      ^bb0(%a: tensor<f32>, %b: tensor<f32>): %s = "stablehlo.add"(%a, %b) : (tensor<f32>, tensor<f32>) -> tensor<f32>
      "stablehlo.return"(%s) : (tensor<f32>) -> ()
    }) {dimensions = array<i64: 1>} : (tensor<4x8xf32>, tensor<f32>) -> tensor<4x1xf32>

    // Step 3: Broadcast sum to match shape of exp_x for division
    %sum_broadcast = "stablehlo.broadcast_in_dim"(%sum_exp) {broadcast_dimensions = array<i64: 1>} : (tensor<4x1xf32>) -> tensor<4x8xf32>

    // Step 4: Divide exp_x by sum_broadcast to get softmax
    %softmax = "stablehlo.divide"(%exp_x, %sum_broadcast) : (tensor<4x8xf32>, tensor<4x8xf32>) -> tensor<4x8xf32>

