    // But since interior padding is uniform, we can specify it as a constant array of 1s.
    // For the padding, we need to specify edge_padding_low, edge_padding_high, interior_padding.
    // The edge paddings are zeros, interior paddings are ones.
    // Create constants for edge paddings:
    %edge_low = "stablehlo.constant"() {value = dense<0 : i64>} : () -> i64
    %edge_high = "stablehlo.constant"() {value = dense<0 : i64>} : () -> i64
