    %edge_padding_high = "stablehlo.constant"() {value = dense<[0,0] : i64>} : () -> tensor<2xi64>
    // Interior padding array:
    %interior_padding = "stablehlo.constant"() {value = dense<[1,1] : i64>} : () -> tensor<2xi64>
    // For 1D tensor, the padding is for dimension 0:
