    // Compute exp(x)
    %exp_x = "stablehlo.exponential"(%x) : (tensor<4x5xf32>) -> tensor<4x5xf32>

    // Reduce exp_x over dimension 1 (columns) to compute sum_k exp(x[i, k])
    %init_sum = "stablehlo.constant"() : () -> tensor<5xf32>
    %sum_exp = "stablehlo.reduce"(%exp_x, %init_sum) ({
      ^bb0(%a: tensor<4x5xf32>, %b: tensor<5xf32>): () {
        // Broadcast %b to match shape for addition
        %b_bcast = "stablehlo.broadcast_in_dim"(%b) {broadcast_dimensions = [1]} : (tensor<5xf32>) -> tensor<4x5xf32>
        // Add broadcasted %b to %a
        %sum = "stablehlo.add"(%a, %b_bcast) : (tensor<4x5xf32>, tensor<4x5xf32>) -> tensor<4x5xf32>
        "stablehlo.return"(%sum) : (tensor<4x5xf32>) -> ()
      }
    }) : (tensor<4x5xf32>, tensor<5xf32>) -> tensor<4x5xf32>

    // Broadcast sum over dimension 1 to match shape for division
    %sum_bcast = "stablehlo.broadcast_in_dim"(%sum_exp) {broadcast_dimensions = [1]} : (tensor<4x5xf32>) -> tensor<4x5xf32>

    // Compute softmax numerator: exp_x / sum_exp
    %softmax_numerator = "stablehlo.divide"(%exp_x, %sum_bcast) : (tensor<4x5xf32>, tensor<4x5xf32>) -> tensor<4x5xf32>

