module {
  func.func @main(%x: tensor<3x5xf32>, %y: tensor<6x5xf32>) -> tensor<3x6xf32> {
    // Step 1: Broadcast x to shape [3,6,5]
    %x_bcast = "stablehlo.broadcast_in_dim"(%x) {broadcast_dimensions = dense_int_array_attr([0, 0]), shape = tensor<3x6x5xf32>} : (tensor<3x5xf32>) -> tensor<3x6x5xf32>
    // Step 2: Broadcast y to shape [3,6,5]
