      dimensions = %reduction_dims,
      kind = "add"
    } : (tensor<3x6x5xf32>, tensor<f32>) -> tensor<3x6xf32>
    // Step 6: Return the result
    return %squared_distances : tensor<3x6xf32>
  }
}
