func.func @main(%idx: tensor<4xi32>) -> tensor<4x8xf32> {
  %c0 = "stablehlo.constant"() {value = dense<0.0> : tensor<f32>} : () -> tensor<f32>
  %c1 = "stablehlo.constant"() {value = dense<1.0> : tensor<f32>} : () -> tensor<f32>
  %c8 = "stablehlo.constant"() {value = dense<8.0> : tensor<f32>} : () -> tensor<f32>

  // Generate iota tensor of shape <4x8> with dimension 1 (columns)
  %iota = "stablehlo.iota"() {iota_dimension = 1 : i64} : () -> tensor<4x8xi32>

  // Broadcast idx to shape <4x8>
  %idx_broadcast = "stablehlo.broadcast_in_dim"(%idx) {broadcast_dimensions = array<i64: 0>} : (tensor<4xi32>) -> tensor<4x8xi32>

  // Compare idx_broadcast with iota to get a boolean mask
  %cmp = "stablehlo.compare"(%idx_broadcast, %iota) {comparison_direction = #stablehlo<comparison_direction LT>, compare_type = #stablehlo<comparison_type FLOAT>} : (tensor<4x8xi32>, tensor<4x8xi32>) -> tensor<4x8xi1>

  // Convert comparison result to float (true -> 1.0, false -> 0.0)
  // Since compare yields i1, cast to f32
  %mask_float = "stablehlo.convert"(%cmp) {to = #stablehlo<convert_type FLOAT>} : (tensor<4x8xi1>) -> tensor<4x8xf32>

  // For idx outside 0..7, mask should be 0, so multiply by 1.0 (or just use mask directly)
  // But since compare is only true for idx == c, the mask is correct as is.

  // The output is the mask as float, representing 1.0 where idx == c, else 0.0
  return %mask_float : tensor<4x8xf32>
}
