func.func @main(%x: tensor<4x5xf32>, %y: tensor<2x5xf32>) -> tensor<4x2xf32>

It must compute: out[i, j] = sum_d (x[i, d] - y[j, d])^2 (squared Euclidean distance between rows).

Relevant operations: broadcast_in_dim, element-wise ops (add/subtract/multiply/divide/maximum/minimum/negate/exponential/sqrt/rsqrt/abs), reduce, constant.

Reply with the complete program in a single ```mlir code block.

```mlir
// StableHLO program to compute pairwise squared Euclidean distances between rows of x and y
module {
  func.func @main(%x: tensor<4x5xf32>, %y: tensor<2x5xf32>) -> tensor<4x2xf32> {
    // Step 1: Broadcast y to shape [4, 2, 5]
    %y_bcast = "stablehlo.broadcast_in_dim"(%y) {
      broadcast_dimensions = [1, 0]
    } : (tensor<2x5xf32>) -> tensor<4x2x5xf32>

    // Step 2: Expand x to shape [4, 1, 5]
    %x_bcast = "stablehlo.broadcast_in_dim"(%x) {
      broadcast_dimensions = [0, 2]
    } : (tensor<4x5xf32>) -> tensor<4x1x5xf32>

    // Step 3: Compute difference: diff = x_bcast - y_bcast
    %diff = "stablehlo.subtract"(%x_bcast, %y_bcast) : (tensor<4x1x5xf32>, tensor<4x2x5xf32>) -> tensor<4x2x5xf32>

    // Step 4: Square the differences: diff_squared = diff * diff
    %diff_squared = "stablehlo.multiply"(%diff, %diff) : (tensor<4x2x5xf32>, tensor<4x2x5xf32>) -> tensor<4x2x5xf32>

    // Step 5: Sum over the last dimension (d=5): sum_d (diff_squared)
    // Initialize reduction with zero
    %zero = "stablehlo.constant"() {value = dense<0.0> : tensor<f32>} : () -> tensor<f32>
    // axes to reduce over: 2 (the last dimension)
    %distances = "stablehlo.reduce"(%diff_squared, %zero) {
      dimensions = [2]
    } : (tensor<4x2x5xf32>, tensor<f32>) -> tensor<4x2xf32> {
      // reduction body: add
      ^bb0(%a: tensor<f32>, %b: tensor<f32>):
        "stablehlo.add"(%a, %b) : (tensor<f32>, tensor<f32>) -> tensor<f32>
    }

    // Output shape: [4, 2]
    return %distances : tensor<4x2xf32>
  }
}
