  %c1 = "stablehlo.constant"() {value = dense<1.0> : tensor<f32>} : () -> tensor<f32>
  %c8 = "stablehlo.constant"() {value = dense<8.0> : tensor<f32>} : () -> tensor<f32>

  // Generate iota tensor of shape [8], values 0..7
  %iota_dim = 0 : i64
  %iota_tensor = "stablehlo.iota"() {iota_dimension = %iota_dim} : () -> tensor<8xi32>

  // Broadcast idx to shape [5,8]
  %bcast_idx = "stablehlo.broadcast_in_dim"(%idx) {broadcast_dimensions = 0 : i64} : (tensor<5xi32>) -> tensor<5x8xi32>

  // Expand iota to shape [5,8]
  %bcast_iota = "stablehlo.broadcast_in_dim"(%iota_tensor) {broadcast_dimensions = array<i64: 1>} : (tensor<8xi32>) -> tensor<1x8xi32>
  %bcast_iota_reshaped = "stablehlo.broadcast_in_dim"(%bcast_iota) {broadcast_dimensions = array<i64: 0>} : (tensor<8xi32>) -> tensor<5x8xi32>

  // Compare idx and iota
  %cmp_idx = "stablehlo.compare"(%bcast_idx, %bcast_iota_reshaped) {comparison_direction = #stablehlo<comparison_direction LT>, compare_type = #stablehlo<compare_type FLOAT>} : (tensor<5x8xi32>, tensor<5x8xi32>) -> tensor<5x8xi1>

  // Convert comparison result to float
  %pred_float = "stablehlo.convert"(%cmp_idx) {to = #stablehlo<convert_type F32>} : (tensor<5x8xi1>) -> tensor<5x8xf32>

  // For positions where idx outside 0..7, set to 0.0
  // Create mask for valid indices: (idx >= 0) & (idx < 8)
  // Since idx >= 0 always true for non-negative, only need to check idx < 8
  // But for simplicity, compare idx with 8
  %cmp_lower = "stablehlo.compare"(%bcast_idx, %c8) {comparison_direction = #stablehlo<comparison_direction LT>, compare_type = #stablehlo<compare_type FLOAT>} : (tensor<5x8xi32>, tensor<8xf32>) -> tensor<5x8xi1>
  // Convert to float mask
  %mask_float = "stablehlo.convert"(%cmp_lower) {to = #stablehlo<convert_type F32>} : (tensor<5x8xi1>) -> tensor<5x8xf32>
  // Final mask: pred_float * mask_float
  %final_mask = "stablehlo.multiply"(%pred_float, %mask_float) : (tensor<5x8xf32>, tensor<5x8xf32>) -> tensor<5x8xf32>

  // The output is the mask: 1.0 where idx == c, 0.0 elsewhere, and 0.0 for invalid idx
  return %final_mask : tensor<5x8xf32>
