// StableHLO program that converts each element of a tensor from float to int32 with truncation
module {
  func.func @main(%x: tensor<10xf32>) -> tensor<10xi32> {
    %zero = constant 0 : index
    %i = "stablehlo.constant"() {value = 0 : index} : () -> index
    %result = "stablehlo.tensor.empty"() : () -> tensor<10xi32>
    // Loop over each element index
    %loop = "stablehlo.for"(%i, %zero) -> (index, tensor<10xi32>) {
      ^bb0(%i: index, %acc: tensor<10xi32>) {
        // Load the element at index i
        %elem = "stablehlo.tensor.extract"(%x, %i) : (tensor<10xf32>, index) -> f32
        // Convert float to int32 with truncation
        %converted = "stablehlo.convert"(%elem) {to = tensor<10xi32>} : (f32) -> i32
        // Insert the converted value into the accumulator tensor
        %acc_updated = "stablehlo.tensor.insert"(%acc, %converted, %i) : (tensor<10xi32>, i32, index) -> tensor<10xi32>
        // Increment index
        %next_i = "stablehlo.add"(%i, %one) : (index, index) -> index
        "stablehlo.cond_br"(%next_i, %acc_updated) {cond = %next_i, then = ^bb1, else = ^bb2}
      }
      ^bb1(%next_i: index, %acc_updated: tensor<10xi32>) {
        // Continue loop
        "stablehlo.br"(%next_i, %acc_updated)
      }
      ^bb2(%next_i: index, %acc_updated: tensor<10xi32>) {
        // Loop finished
        "stablehlo.return"(%acc_updated) : tensor<10xi32>
      }
    }
    // The loop returns the final tensor
    return %result : tensor<10xi32>
  }
}
